  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * 1. Summary: Computes the final booking price applying a 20% discount if the customer holds a DISCOUNTS award and books >= 24h before departure.
   * 2. Algorithm: 
   *    1. If customer is null or customer.membershipPackage is null or !customer.membershipPackage.hasAward(DISCOUNTS), return round(this.price, 1).
   *    2. If bookingTime is invalid or cannot be parsed, return round(this.price, 1).
   *    3. Parse bookingTime and combine with this.departureDate and this.departureTime to form comparable datetime objects. Calculate time difference in hours.
   *    4. If difference >= 24.0, discountedPrice = this.price * 0.8. Else discountedPrice = this.price.
   *    5. Round discountedPrice to 1 decimal place using standard half-up rounding.
   *    6. Return result.
   * 3. Related Features: price, departureDate, departureTime, customer, membershipPackage, awards
   * 4. Related Classes: Customer, MembershipPackage, Award
   * 5. Input: customer : Customer - Booking customer; bookingTime : String - Time of booking in "YYYY-MM-DD HH:MM" format
   * 6. Output: double - Final price rounded to 1 decimal place
   * 7. Pre-condition: this.price >= 0.
   * 8. Post-condition: Returns original price rounded to 1 decimal if discount conditions fail, inputs are invalid, or timing is insufficient; otherwise returns discounted price rounded to 1 decimal.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || customer.getMembershipPackage() == null || !customer.getMembershipPackage().hasAward(Award.DISCOUNTS)) {
      return new BigDecimal(Double.toString(this.price)).setScale(1, RoundingMode.HALF_UP).doubleValue();
    }
    try {
      LocalDateTime bookingDt = LocalDateTime.parse(bookingTime.replace(' ', 'T'));
      LocalDateTime departDt = LocalDateTime.ofInstant(this.departureDate.toInstant(), ZoneId.systemDefault())
              .toLocalDate().atTime(LocalTime.parse(this.departureTime));
      double diffHours = Duration.between(bookingDt, departDt).toSeconds() / 3600.0;
      if (diffHours < 0) diffHours = -diffHours;
      double discountedPrice = diffHours >= 24.0 ? this.price * 0.8 : this.price;
      return new BigDecimal(Double.toString(discountedPrice)).setScale(1, RoundingMode.HALF_UP).doubleValue();
    } catch (Exception e) {
      return new BigDecimal(Double.toString(this.price)).setScale(1, RoundingMode.HALF_UP).doubleValue();
    }
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * 1. Summary: Calculates points earned specifically from bookings of this trip made by the given customer within the target month.
   * 2. Algorithm: 
   *    1. If customer is null or customer.membershipPackage is null or !customer.membershipPackage.hasAward(POINTS), return 0.
   *    2. points = 0.
   *    3. For each b in this.bookings: if b.customer == customer and b.isInMonth(currentMonth), points += b.numberOfSeats * 5.
   *    4. Return points.
   * 3. Related Features: bookings, customer, membershipPackage, awards
   * 4. Related Classes: Booking, Customer, MembershipPackage, Award
   * 5. Input: customer : Customer, currentMonth : String ("YYYY-MM")
   * 6. Output: int - Points calculated for this trip's bookings
   * 7. Pre-condition: this.bookings is initialized. currentMonth is in valid format.
   * 8. Post-condition: Returns sum of (seats * 5) for matching bookings; returns 0 if customer is invalid, membership package is missing, or award is unsupported.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || customer.getMembershipPackage() == null || !customer.getMembershipPackage().hasAward(Award.POINTS)) {
      return 0;
    }
    int points = 0;
    for (Booking b : this.getBookings()) {
      if (b.getCustomer() == customer && b.isInMonth(currentMonth)) {
        points += b.getNumberOfSeats() * 5;
      }
    }
    return points;
  }

